create or replace function private.field_job_readiness() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if not public.has_permission_for_current_user('field_app') then raise exception 'Field permission required'; end if; return coalesce((select jsonb_agg(jsonb_build_object('jobId',j.id,'agreement',coalesce((select jsonb_build_object('name',a.name,'status',a.status,'visitsRemaining',a.visits_remaining) from public.service_agreements a where a.customer_id=j.customer_id and a.status='active' order by a.created_at desc limit 1),'null'::jsonb),'equipmentCount',(select count(*) from public.customer_equipment e where e.customer_id=j.customer_id and e.status='active'),'openEstimateCount',(select count(*) from public.estimates es join public.jobs ej on ej.id=es.job_id where ej.customer_id=j.customer_id and es.status in ('draft','sent')),'priorJobCount',(select count(*) from public.jobs p where p.customer_id=j.customer_id and p.id<>j.id and p.status in ('work_complete','completed')))) from public.jobs j where j.status in ('scheduled','dispatched','en_route','on_site') and (public.current_user_role()<>'technician' or j.technician_id=auth.uid())),'[]'::jsonb); end $$;
create or replace function public.field_job_readiness() returns jsonb language sql stable set search_path='' as $$ select private.field_job_readiness() $$; revoke all on function public.field_job_readiness() from public,anon; grant execute on function public.field_job_readiness() to authenticated;